"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[7233],{63799(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>i,default:()=>c,frontMatter:()=>a,metadata:()=>r,toc:()=>l});var n=o(74848),s=o(28453);const a={title:"Where Does the Chaos Go? (3): Each Time the Problem Gets Worse, Someone Gets Promoted",sidebar_label:"3. Each Time the Problem Gets Worse, Someone Gets Promoted",slug:"/chaos-series/problem-worse-person-promoted",date:new Date("2026-11-23T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"chaos-series",category:"\u8cc7\u672c\u8207\u9000\u51fa\u6a5f\u5236",article_tags:{zh:["\u91d1\u878d\u5316","\u7ba1\u7406\u5c64","\u7814\u767c","\u58df\u65b7","\u92b7\u552e"],en:["financialization","management","r-and-d","monopoly","sales"]},keywords:["legacy","workaround","X-inefficiency","bullshit jobs","zombie firms"],summary:"The problem sinks while the person who built it rises: filterers, inherited seats, three-month scoreboards, and the monopoly margin that pays for it all.",description:"The problem sinks while the person who built it rises: filterers, inherited seats, three-month scoreboards, and the monopoly margin that pays for it all.",status:"published",reading_time:20,series:{order:3}},i="Where Does the Chaos Go? (3): Each Time the Problem Gets Worse, Someone Gets Promoted",r={id:"series/chaos-series/problem-worse-person-promoted",title:"Where Does the Chaos Go? (3): Each Time the Problem Gets Worse, Someone Gets Promoted",description:"The problem sinks while the person who built it rises: filterers, inherited seats, three-month scoreboards, and the monopoly margin that pays for it all.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/series/chaos-series/03-problem-worse-person-promoted.md",sourceDirName:"series/chaos-series",slug:"/chaos-series/problem-worse-person-promoted",permalink:"/en/docs/chaos-series/problem-worse-person-promoted",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:3,frontMatter:{title:"Where Does the Chaos Go? (3): Each Time the Problem Gets Worse, Someone Gets Promoted",sidebar_label:"3. Each Time the Problem Gets Worse, Someone Gets Promoted",slug:"/chaos-series/problem-worse-person-promoted",date:"2026-11-23T00:00:00.000Z",lang:"en",section:"sober-record",topic:"chaos-series",category:"\u8cc7\u672c\u8207\u9000\u51fa\u6a5f\u5236",article_tags:{zh:["\u91d1\u878d\u5316","\u7ba1\u7406\u5c64","\u7814\u767c","\u58df\u65b7","\u92b7\u552e"],en:["financialization","management","r-and-d","monopoly","sales"]},keywords:["legacy","workaround","X-inefficiency","bullshit jobs","zombie firms"],summary:"The problem sinks while the person who built it rises: filterers, inherited seats, three-month scoreboards, and the monopoly margin that pays for it all.",description:"The problem sinks while the person who built it rises: filterers, inherited seats, three-month scoreboards, and the monopoly margin that pays for it all.",status:"published",reading_time:20,series:{order:3}},sidebar:"lucidRecord",previous:{title:"2. The Monster Becomes a Seat",permalink:"/en/docs/chaos-series/the-monster-becomes-a-seat"},next:{title:"4. The Last Field Never Names the Company",permalink:"/en/docs/chaos-series/the-last-field-never-names-the-company"}},h={},l=[{value:"Prologue: Two Lines Moving in Opposite Directions",id:"prologue-two-lines-moving-in-opposite-directions",level:2},{value:"1. Where the Filterers Come From",id:"1-where-the-filterers-come-from",level:2},{value:"2. The Intake: Data Records Only What Gets Through",id:"2-the-intake-data-records-only-what-gets-through",level:2},{value:"3. The Seat That Takes Over",id:"3-the-seat-that-takes-over",level:2},{value:"4. Where the Money Went",id:"4-where-the-money-went",level:2},{value:"5. After the Cut: R&amp;D Becomes Procurement",id:"5-after-the-cut-rd-becomes-procurement",level:2},{value:"6. A Three-Month Scoreboard",id:"6-a-three-month-scoreboard",level:2},{value:"7. The Highest Pay Goes to the Seat Waiting to Be Replaced",id:"7-the-highest-pay-goes-to-the-seat-waiting-to-be-replaced",level:2},{value:"8. Who Pays the Bill",id:"8-who-pays-the-bill",level:2},{value:"9. Companies That Cannot Die",id:"9-companies-that-cannot-die",level:2},{value:"Summary",id:"summary",level:2},{value:"Notes",id:"notes",level:2}];function d(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"where-does-the-chaos-go-3-each-time-the-problem-gets-worse-someone-gets-promoted",children:"Where Does the Chaos Go? (3): Each Time the Problem Gets Worse, Someone Gets Promoted"})}),"\n",(0,n.jsx)(t.p,{children:"@Mythogen Engine \xb7 Nov 23, 2026"}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsxs)(t.em,{children:['The previous article, "',(0,n.jsx)(t.a,{href:"/en/docs/chaos-series/the-monster-becomes-a-seat",children:"The Monster Becomes a Seat"}),'," argued that the gap settles in the organization over many years into a monster nobody understands, and that in a shrinking company, controlling the monster is the same as holding a seat. This article is about the people who guard the seat.']})}),"\n",(0,n.jsx)(t.h2,{id:"prologue-two-lines-moving-in-opposite-directions",children:"Prologue: Two Lines Moving in Opposite Directions"}),"\n",(0,n.jsx)(t.p,{children:"A problem and a person can move in opposite directions inside the same company."}),"\n",(0,n.jsx)(t.p,{children:"The problem's path goes down: it appears, gets filtered, gets put away, becomes legacy; the money allocated to rebuild it is diverted; the company finally buys a new product line and clears out the old system together with the people who maintained it."}),"\n",(0,n.jsx)(t.p,{children:"The person's path goes up: an engineer builds a system, solves the problem of the day, and becomes a legend; he adds an MBA and moves into a filtering position; he is promoted to director; finally he leaves for another company carrying an impressive CV."}),"\n",(0,n.jsxs)(t.p,{children:["The two lines are two sides of the same thing: ",(0,n.jsx)(t.strong,{children:"each time the problem gets worse, the person who built it moves up a level."})]}),"\n",(0,n.jsxs)(t.p,{children:["This article walks along both lines. The arrangement needs no villains to work, which is the same position ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door",children:(0,n.jsx)(t.em,{children:"Who's Collecting at the Door"})})," takes throughout; but it does select for, and reward, a certain kind of person. That part is for the next article."]}),"\n",(0,n.jsx)(t.h2,{id:"1-where-the-filterers-come-from",children:"1. Where the Filterers Come From"}),"\n",(0,n.jsx)(t.p,{children:"The people guarding the intake of problems are usually not outsiders. Most of the ones I have seen came from engineering or R&D and later added an MBA, a doctorate or an EMBA. Further up, at senior director and above, they are essentially businesspeople."}),"\n",(0,n.jsx)(t.p,{children:"The power of this position comes from speaking two languages at once. Downward, he can use the same terminology as the engineers, and can use technical authority to dismiss the problems they raise. Upward, he translates technical reality into cost, risk and profit. The people above cannot understand engineering language, so every technical reality has to pass through his translation to reach them. What gets translated, how, and how serious it sounds: he decides."}),"\n",(0,n.jsx)(t.p,{children:"Nor has he given up being an engineer. He keeps both identities and switches between them as needed. To get promoted or talk to the boss, he is a businessman; to keep the engineers below him in line or to intervene in technical specifications, he stresses how deep his technical roots go. The technical identity becomes a tool of authority rather than a capability still in use. His technical knowledge may be ten years out of date; his technical authority is not."}),"\n",(0,n.jsx)(t.p,{children:'The crucial point is this: very often, the legacy from years ago was built by these very people. They are the legends who "got that system working" back then, and their standing rests on that signature work. So what they filter is not neutral problems but their own past decisions. Admitting the legacy has a fundamental flaw means admitting their signature work is flawed; whenever someone below suggests a rebuild, they have every incentive to say "a workaround will do."'}),"\n",(0,n.jsx)(t.p,{children:"This does not require them to be bad people. Protecting one's reputation is a rational response to the step before: as long as admitting the error costs more than putting the problem away, the outcome is the same. And when they use outdated technical understanding today to shape new specifications, they are building the next generation of legacy."}),"\n",(0,n.jsxs)(t.p,{children:["These are not the same people as the highly credentialled figures in chapter one of ",(0,n.jsx)(t.em,{children:"Who's Collecting at the Door"}),". That chapter describes signals bought in from outside, placed in a CTO seat to gain external credibility; this article describes insiders who built legacy and became legends. Both kinds can coexist in the same company."]}),"\n",(0,n.jsx)(t.h2,{id:"2-the-intake-data-records-only-what-gets-through",children:"2. The Intake: Data Records Only What Gets Through"}),"\n",(0,n.jsx)(t.p,{children:"Everyone can see Excel's chaos; once it moves to Jira, the chaos is tucked into the intake. What can be ticketed, at what severity, split into how many tickets, described in what words: all of it is decided by whoever does the filtering. Every ticket in the system is neat and tidy."}),"\n",(0,n.jsxs)(t.p,{children:['The data does not show the problem because it records only what gets through. What was never ticketed, merged into another ticket, downgraded, or closed as "cannot reproduce" or "client-side issue" all shows up on the dashboard as healthy metrics: high close rates, short handling times, small backlogs. The same problem keeps recurring, and each time it is a fresh ticket marked "resolved." The better the report looks, the worse reality may be. This is what chapter six of ',(0,n.jsx)(t.em,{children:"Who's Collecting at the Door"})," calls the demand for closure: the ticket has to be closed, not the problem solved."]}),"\n",(0,n.jsx)(t.p,{children:'Every layer of management does the same thing. Management describes itself as "consolidating, filtering, making things manageable," but in essence it compresses information: ten things below become three reported upward, and three become one sentence. What gets deleted first in compression is precisely the anomaly, because it does not fit the format, is hard to explain, and makes the report look bad. The irony is that everyone demands "lossless integration" between Excel and ERP, while the lossiest interface in the organization is layer after layer of management.'}),"\n",(0,n.jsx)(t.p,{children:"I have stood on the other side myself. When I was sent from headquarters to oversee several regions, all I wanted was the data and whether targets were met; how things worked internally, who took the blame for whom, had no box in my report. As I said in the previous article, I could smell that the numbers were off but had no authority to investigate. The other half is this: even when the numbers are off, as long as the final result is right, nobody goes digging for the cause without reason. How the result was pushed up could be a genuinely good market, or channel stuffing, or pulling next quarter's sales forward; whether to know the reason becomes a choice in itself, and people usually choose not to know."}),"\n",(0,n.jsxs)(t.p,{children:["That is the misalignment at the intake: ",(0,n.jsx)(t.strong,{children:"those who can see have no power, and those with power do not want to look."})," The filterer does not need to hide things perfectly; he only needs to make investigating cost more than not investigating. When the people above look only at numbers, his job naturally becomes managing the information flowing upward, and whoever makes the numbers cleanest rises fastest."]}),"\n",(0,n.jsx)(t.p,{children:'This is also why "use AI for triage" does not solve the problem. If the model is trained on past tickets that were already filtered, it learns the filterer\'s blind spots along with everything else, and gains a coat of "objectivity" that makes it harder to challenge.'}),"\n",(0,n.jsx)(t.h2,{id:"3-the-seat-that-takes-over",children:"3. The Seat That Takes Over"}),"\n",(0,n.jsx)(t.p,{children:"After the legend moves up, someone has to inherit the system he left behind. The situation in that seat is roughly this: yields are poor to begin with, yet the requirements rise every year; the previous holder could not cope and left, so someone is found to fill in; when they cannot cope either, another replaces them."}),"\n",(0,n.jsx)(t.p,{children:"Each change of person makes the system harder to handle. The previous holder already had no solution and left behind a pile of stacked workarounds; the new person lacks their predecessor's memory and starts from a worse position, so all they can do is add another layer. Every holder gives everything they have, and all any of them achieves is making the problem invisible for a while."}),"\n",(0,n.jsx)(t.p,{children:"Why can this seat never keep people, yet always find someone new? Because in the accounts it sits in the wrong place. The revenue from the legacy product is credited to the product line and to sales; the people maintaining it are booked under a cost center. A cost center moves in only one direction: down. The position that does the most to hold up revenue, and is the hardest to do, appears on the statements only on the cost side."}),"\n",(0,n.jsx)(t.p,{children:'The terms the company offers for this seat are often better than outsiders imagine: promotion, a raise, more authority. But look closely at what that "authority" includes. Is there a budget to rebuild? Is there the power to say "without a rebuild there is no solution" and actually be heard? If not, it is only authority over workarounds. Whoever takes the seat knows from the start they cannot solve the problem, and can only find ways to build another workaround and cover it further. The fact that holder after holder has left is the best evidence of what this seat is.'}),"\n",(0,n.jsx)(t.p,{children:"Someone will ask: this is exactly the kind of person every big company needs most. Isn't it foolish not to take the seat? First, the next section looks at another common answer: then fund a rebuild."}),"\n",(0,n.jsx)(t.h2,{id:"4-where-the-money-went",children:"4. Where the Money Went"}),"\n",(0,n.jsx)(t.p,{children:"Even when money is allocated, it does not go into a rebuild. I once saw a sum of over ten million US dollars, nominally for research and development, turn into repairs, maintenance and renovation once it reached the factory, along with assorted other things. Nobody actually used it to redesign a system."}),"\n",(0,n.jsx)(t.p,{children:"Money in an organization is fungible, and it naturally flows to the safest place. Repairs and renovation produce immediate, visible results and cannot fail; redevelopment takes years, may fail, and the manager may have changed halfway through. So a sum labelled \"R&D,\" as it passes through each layer, gets used to fill that layer's most urgent hole. More ironic still, it often ends up extending the legacy system's life."}),"\n",(0,n.jsxs)(t.p,{children:["The R&D department itself is the same. The name remains, but everyone inside is doing PE, product engineering: keeping shipments going, handling complaints, making small spec changes. The name is useful: to investors, the R&D spending ratio looks good; to government, it qualifies for subsidies and tax breaks; to the public, it lets you talk about innovation. The name serves capital markets and subsidies; the content serves short-term cash flow. R&D has become a financial label rather than an activity. Chapter one of ",(0,n.jsx)(t.em,{children:"Who's Collecting at the Door"})," covered R&D surviving in name only; the other half here is that even when money really is allocated for a rebuild, it flows away."]}),"\n",(0,n.jsx)(t.p,{children:"The most serious consequence is the loss of capability. After a few years of the whole R&D department doing PE, nobody in the company knows how to design a new system from scratch anymore. Even if one day someone has the determination, the money and the authority to rebuild, the capability is gone. The previous article described problems going from solvable to unsolvable; this is about the people who could solve them disappearing too."}),"\n",(0,n.jsx)(t.h2,{id:"5-after-the-cut-rd-becomes-procurement",children:"5. After the Cut: R&D Becomes Procurement"}),"\n",(0,n.jsx)(t.p,{children:"The previous article said legacy can be cut, only it is always delayed until it must be. This section looks at what happens after the cut."}),"\n",(0,n.jsx)(t.p,{children:"The company need not worry about lacking R&D capability, because it knows full well that R&D has been doing PE all along. For the next generation of products, the simplest move is to buy: acquire a design house, or start a new line. The old legacy becomes old reference material, old specs, kept for reference only and not followed."}),"\n",(0,n.jsx)(t.p,{children:'Seen this way, the role of the people guarding the legacy is clear: they are a bridge, there to hold up the old product\'s cash flow until the new capability is bought in. Once the new line is ready, the bridge can come down. The years of knowledge they accumulated inside the workarounds are worth almost nothing on handover day, because the new system has no need to know how the old one limped along. In that seat, there is not even "accumulation" to speak of; everything you put in is wiped out at the moment of transition.'}),"\n",(0,n.jsx)(t.p,{children:"And it is a cycle. The design house that was bought gets fitted with big-company processes after integration and is asked to support shipments, and its R&D slowly turns into PE. A few years later it is the next generation of legacy, and the company buys the next one. In companies like this, R&D has become a procurement activity rather than a capability."}),"\n",(0,n.jsx)(t.p,{children:'But there is one thing that cannot be bought back. Inside the old workarounds are real constraints: a particular customer\'s special requirement, the temperament of a certain material, why a certain process has to be tuned just so. When the new line says "reference only, no need to follow," it often steps on the same set of mines again. It is just that this cost falls on the new team and the customers, appears years later, and does not exist in the calculation at the moment of acquisition.'}),"\n",(0,n.jsx)(t.h2,{id:"6-a-three-month-scoreboard",children:"6. A Three-Month Scoreboard"}),"\n",(0,n.jsx)(t.p,{children:"The clearest example of who gets rewarded and who gets punished is in sales."}),"\n",(0,n.jsx)(t.p,{children:'About six months before the market announcement, the channel sales team already knew from partner briefings how the platform would define the AI PC and how it would be layered onto a replacement wave. The replacement wave itself was no secret; the end-of-support date for Windows 10 had long been public. What they had was the plan for packaging a public deadline as a new product. I concluded at the time, from the hardware and the software ecosystem, that the label could not live up to the word "AI": the NPU had no killer application, and the real compute-heavy work still depended on the GPU. Their reaction was contempt: you don\'t even know what happens next, so what are you doing talking about fundamentals?'}),"\n",(0,n.jsx)(t.p,{children:'But that briefing came with the seat, not with the person. Anyone sitting in that channel position would have received it. Their arrogance was to mistake a perk that came with the seat for their own judgment, and then use it to look down on people who did not sit there. Yet the part that actually requires judgment, whether the script would hold up once launched, is exactly what the briefing could not answer. What they knew was the script; what I inferred was the ending. Knowing the script early is not the same as knowing the ending, but until the ending arrives, nobody can tell the two apart. Later, the platform\'s flagship feature, Recall, was delayed over privacy concerns, and "no software support" became fact.'}),"\n",(0,n.jsx)(t.p,{children:"Nor were they blind to the long term. Customers' doubts stretching a year or two out, technical limits, budget shifts: they heard all of it. They just did not care, because targets and commissions were counted in three months. A genuine data-collection or test cycle itself takes three months; a quarter's \"strategy\" cannot even see its own results before the next quarter begins. That is not strategy, only one more delivery against the numbers."}),"\n",(0,n.jsx)(t.p,{children:"This also explains why the contempt flows only one way. The short-term side judges long-term views by a short-term scoreboard: Did it make money this quarter? Can you name the day? The long-term side cannot give a date, so in that frame it always scores zero. In the other direction, long-term judgment does not need that channel information and is not overturned by it, so it has no reason to look down in return."}),"\n",(0,n.jsx)(t.p,{children:"And their arrogance is backed by a payslip. Salespeople's pay and commissions are higher than engineers', and what they earn in the years they hit their numbers is more than an engineer can catch up with in a lifetime. The market and the company have both proved, in hard cash, that their way of counting is \"right.\" Besides, they come and go quickly, taking the commission and moving to another company; by the time the cycle turns, the goods stop selling and inventory piles up, they are at the next company working the next script."}),"\n",(0,n.jsx)(t.p,{children:"The one who most directly inherits the consequences is often not the engineer but the next salesperson. The predecessor stuffed the channel or booked fake orders and collected the bonus; the successor inherits an inflated baseline: customer returns, channel backlog, and a new target set from last year's fake numbers. An honest successor will always look worse than the predecessor in the first year. Reward and punishment are exactly reversed: the one who faked it gets the prize, the one who inherits it takes the blame. Over ten or twenty years this has become almost standard practice. Even where things improve, the techniques only get more refined rather than disappearing, because every layer of the chain benefits, and nobody who stays in place has any incentive to reopen old accounts."}),"\n",(0,n.jsx)(t.p,{children:"To be fair, both sides can be right at once. Riding the Windows 11 replacement wave, AI PCs really did sell; it is just that selling had nothing to do with AI. Short-term structures sometimes hold up longer than long-term judgment expects. The problem is not who is right, but that the scoreboard records only one kind of right."}),"\n",(0,n.jsxs)(t.p,{children:['Society used to have at least some balance here. The people who looked far ahead did not necessarily earn the most, but there were always positions from which one could say "no," where one stayed long enough for what one had said to be remembered. The veto power described in chapter one of ',(0,n.jsx)(t.em,{children:"Who's Collecting at the Door"}),' is one such thing. Financialization has whittled that balance down to almost nothing: the scoreboard is now only quarterly, the positions that could say "no" have been taken away, and people with long memories are treated as unable to keep up. Those who benefit go further and package all of this as progress and adaptation: markets move fast, be agile, keep up with the times. Those who don\'t adapt are called outdated; those who do adapt have only learned to look three months ahead.']}),"\n",(0,n.jsx)(t.h2,{id:"7-the-highest-pay-goes-to-the-seat-waiting-to-be-replaced",children:"7. The Highest Pay Goes to the Seat Waiting to Be Replaced"}),"\n",(0,n.jsx)(t.p,{children:"Oddly, the seat waiting to be replaced may be the one paid most."}),"\n",(0,n.jsx)(t.p,{children:"This is not a contradiction; the pricing is actually accurate. The company needs you to hold up cash flow until the new line is ready, needs you not to leave, and needs you to accept that you will be wiped out later. All three together still cost less than redevelopment, and the company knows this money has a time limit and a capped cost, so it is willing to pay a lot. High pay buys not your future but your present, and your silence. In financial terms it is like a high-yield bond: the yield is high because the chance of default is high."}),"\n",(0,n.jsx)(t.p,{children:"But that analogy misses the most important point: very often it never defaults. The cost of the blow-up falls not on the person in this seat but on whoever takes over after they leave, on the customers, or on the whole unit. Some people sit in it for five to ten years, get promoted, then jump ship with an impressive CV, and the problem only blows up after they are gone."}),"\n",(0,n.jsxs)(t.p,{children:['So be clear about what this position accumulates. The engineering knowledge really cannot be transferred: "how this particular heap works" has no market outside this company. But another set of skills can be transferred, and is very valuable: how to make numbers look good, how to delay, how to push problems outward. Promotion and the jump to another company rely on exactly this set. An organization that promotes whoever has the cleanest numbers year after year will, after a decade or so, have a management layer made of people filtered for their skill at covering things up; when they move to a new company, they bring the same set with them. Chapter one of ',(0,n.jsx)(t.em,{children:"Who's Collecting at the Door"})," said the settlement period for promises is longer than the promotion cycle; what we see here is how that time gap selects people, generation after generation."]}),"\n",(0,n.jsx)(t.p,{children:"Back to the question in section three: is it foolish not to take this seat? I would say neither the people who take it nor the people who refuse it are fools. Someone who takes it knowing they are being paid time-limited compensation, negotiates terms first, saves the extra money and keeps their skills alive outside, is making a rational choice; they just have to admit that the work they are doing is covering things up. The person who really loses is the one who takes the highest pay while believing they are building a career: they use money that compensates them for a future that will be zeroed out to buy a future that does not exist."}),"\n",(0,n.jsx)(t.p,{children:"As for refusing, the difference is not cleverness or foolishness but whether you are willing to sell this particular thing. Taking the seat, what you sell is not technical skill but your willingness to carry a result that is bound to fail, and to help cover it up."}),"\n",(0,n.jsx)(t.h2,{id:"8-who-pays-the-bill",children:"8. Who Pays the Bill"}),"\n",(0,n.jsx)(t.p,{children:"At this point a more fundamental question arises: the filtering layer, the workarounds, the successors who get cheaper each time, the diverted budgets, the bullshit jobs and the infighting are all costs. How can a company afford so much chaos, and still win?"}),"\n",(0,n.jsx)(t.p,{children:"The answer is the profit from synergies and monopoly. Large companies' advantages of scale are real: purchasing leverage, distribution channels, brand, customer lock-in, market position. But these advantages do not become lower prices or better quality; they are eaten up internally. What scale saves is just about enough to pay for the organization's disease. The result is a more expensive way to make a worse product that still wins, because what wins is not production efficiency but market position."}),"\n",(0,n.jsx)(t.p,{children:'Economics has a name for this: X-inefficiency. A firm without enough competitive pressure keeps its actual costs above what it could achieve for long periods, and the difference is consumed inside the organization.\xb9 There is an even older line: the best of all monopoly profits is a quiet life.\xb2 The "bullshit jobs" the anthropologist Graeber described are also positions fed by this margin.\xb3'}),"\n",(0,n.jsx)(t.p,{children:"This also explains the situation of small companies. Small companies are not incapable; they cannot reach volume. They lack this monopoly margin, so they cannot afford chaos, and every unit of cost has to go straight into the product. Large companies can reach volume, yet cannot match on quality or price, because their cost structure is packed with things that do not belong to the product. This hidden cost is invisible because it has no line of its own; it is spread across salaries, overheads, delays and quality."}),"\n",(0,n.jsx)(t.p,{children:"So what the monopoly margin really buys is time. As long as the margin exists, chaos can be kept inside the organization; once it narrows and the pie stops growing, the chaos can no longer be contained and starts being passed on to customers' quality and to employees. The previous article's point that \"whether people fight depends on room\" is the same thing: when the pie shrinks, infighting becomes the only way to stay."}),"\n",(0,n.jsx)(t.h2,{id:"9-companies-that-cannot-die",children:"9. Companies That Cannot Die"}),"\n",(0,n.jsx)(t.p,{children:"A company run this way should have an ending: eaten by competitors, it either goes bust or is acquired and restructured. The process is painful, but it clears things out. This is the market's death mechanism."}),"\n",(0,n.jsx)(t.p,{children:'The real danger is when the death mechanism is taken away. Government subsidies, banks rolling over loans indefinitely, monopoly positions or political protection can all keep these companies from dying. Japan\'s "zombie firms" of the 1990s are the classic example: banks would not recognize bad debts and kept lending to hopeless companies, resources and talent were trapped inside, healthy firms found it harder to enter and expand, and the economy stagnated for years.\u2074'}),"\n",(0,n.jsxs)(t.p,{children:["So I would not call this culture the cause of a country's disease. The culture is the symptom; the failure of the exit mechanism is the cause. As long as failing companies still die, the culture is just one company's chronic illness; once the whole system protects them from dying, it spreads into national-level stagnation in productivity and a hollowing-out of capability. The monopoly margin from earlier becomes, at this level, a margin protected by the system: nobody forces these companies to face their real costs. This is the same thing my ",(0,n.jsxs)(t.a,{href:"/en/docs/TechNotes/%E9%80%80%E5%87%BA%E6%A9%9F%E5%88%B6%E4%B8%89%E9%83%A8%E6%9B%B2",children:[(0,n.jsx)(t.em,{children:"Exit Mechanism"})," trilogy"]})," described, only moved from money and land into organizations."]}),"\n",(0,n.jsx)(t.p,{children:"This also gives the post at the start of the first article another layer of meaning. A small team plus AI can build seventy percent of Photoshop's everyday features, which shows that capability was never the barrier; scale was. If what AI lowers is exactly the barrier of scale, then what it threatens is that monopoly margin, the money that keeps the whole organizational disease alive. In a sense, this amounts to reinstalling a death mechanism: when outsiders can rebuild your product at far below your cost, companies held together by workarounds and cover-ups cannot drag on so easily."}),"\n",(0,n.jsx)(t.p,{children:"But a mechanism that can be reinstalled can also be taken away again. Patents, platform lock-in, certification thresholds and subsidies can all seal it back up; the AI PC label in the previous article is an example of a platform keeping the power of definition in its own hands. Whether AI ends up as a new death mechanism or a new tool of monopoly depends on who controls those thresholds, not on the technology itself."}),"\n",(0,n.jsx)(t.h2,{id:"summary",children:"Summary"}),"\n",(0,n.jsx)(t.p,{children:"The problem and the person move in opposite directions through a series of arrangements, each reasonable on its own: the filterer monopolizes translation, and the data records only what gets through; the seat that takes over is booked under a cost center and gets cheaper with each holder; the scoreboard runs only three months, so those who look short-term are rewarded and those who look long-term are punished; money for rebuilding flows to the safest place; R&D becomes procurement; the skill of covering up transfers, engineering knowledge does not; the monopoly margin pays the bill, and the system protects it from dying."}),"\n",(0,n.jsx)(t.p,{children:"The gap is created by promises, lands first on the desktop, is then absorbed into the organization, and is paid for by the monopoly margin. When the margin can no longer cover it, it falls on people."}),"\n",(0,n.jsx)(t.p,{children:"The next article is about whom that bill finally lands on, and why the records never carry the company's name."}),"\n",(0,n.jsxs)(t.p,{children:['Next: "',(0,n.jsx)(t.a,{href:"/en/docs/chaos-series/the-last-field-never-names-the-company",children:"The Last Field Never Names the Company"}),'."']}),"\n",(0,n.jsx)(t.h2,{id:"notes",children:"Notes"}),"\n",(0,n.jsxs)(t.ol,{children:["\n",(0,n.jsxs)(t.li,{children:["Harvey Leibenstein, \"Allocative Efficiency vs. 'X-Efficiency',\" ",(0,n.jsx)(t.em,{children:"American Economic Review"}),", 56(3), 1966, pp. 392\u2013415."]}),"\n",(0,n.jsxs)(t.li,{children:['John R. Hicks, "Annual Survey of Economic Theory: The Theory of Monopoly," ',(0,n.jsx)(t.em,{children:"Econometrica"}),', 3(1), 1935, pp. 1\u201320. The original line is "The best of all monopoly profits is a quiet life."']}),"\n",(0,n.jsxs)(t.li,{children:["David Graeber, ",(0,n.jsx)(t.em,{children:"Bullshit Jobs: A Theory"}),", Simon & Schuster, 2018."]}),"\n",(0,n.jsxs)(t.li,{children:['Ricardo J. Caballero, Takeo Hoshi and Anil K. Kashyap, "Zombie Lending and Depressed Restructuring in Japan," ',(0,n.jsx)(t.em,{children:"American Economic Review"}),", 98(5), 2008, pp. 1943\u20131977."]}),"\n"]})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,t,o){o.d(t,{R:()=>i,x:()=>r});var n=o(96540);const s={},a=n.createContext(s);function i(e){const t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);